t = int(input())
for _ in range(t):
	a = input() + '00'
	b = input() + '00'
	b1 = False
	b2 = False
	c = 0
	for i in range(len(a)):
		if i % 2 == 0:
			if int(a[i]) ^ int(b[i]) == 1:
				b1 = True
			else:
				if b1:
					c += 1
				b1 = False
		elif int(a[i]) ^ int(b[i]) == 1:
			b2 = True
		else:
			if b2:
				c += 1
			b2 = False
	print(c)
